using AiOps;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
var builder = WebApplication.CreateBuilder(args);
var port = int.Parse(Environment.GetEnvironmentVariable("AIOPS_PORT") ?? "5080");
builder.WebHost.ConfigureKestrel(o => { o.Listen(IPAddress.Loopback, port); o.Limits.MaxRequestBodySize = 262144; });
builder.Logging.ClearProviders(); // Never log URLs, payloads or secrets in the MVP.
builder.Services.AddSingleton(new Store(Environment.GetEnvironmentVariable("AIOPS_DB") ?? "data/aiops.db"));
builder.Services.AddSingleton<Egress>(); builder.Services.AddSingleton<IDiagnoser, Diagnoser>(); builder.Services.AddHostedService<IncidentWorker>();
var app = builder.Build();
app.Use(async (ctx, next) =>
{
    ctx.Response.Headers["X-Content-Type-Options"] = "nosniff"; ctx.Response.Headers["Content-Security-Policy"] = "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'";
    if (ctx.Request.Host.Host is not ("127.0.0.1" or "localhost")) { ctx.Response.StatusCode = 403; return; }
    if (ctx.Request.Headers.TryGetValue("Origin", out var origin) && origin != $"http://{ctx.Request.Host}") { ctx.Response.StatusCode = 403; return; }
    if (ctx.Request.Path.StartsWithSegments("/api") && ctx.Request.Method is not ("GET" or "HEAD") && !ctx.Request.Path.StartsWithSegments("/api/webhooks") && ctx.Request.Headers["X-Aiops-Client"] != "workbench") { ctx.Response.StatusCode = 403; return; }
    try { await next(); } catch (ArgumentException ex) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = ex.Message }); } catch (BadHttpRequestException) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = "请求无效或超过大小限制" }); } catch (KeyNotFoundException) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = "缺少必填 JSON 字段" }); } catch (InvalidOperationException) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = "字段类型或操作无效" }); } catch (JsonException) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = "JSON 格式无效" }); } catch (HttpRequestException) { ctx.Response.StatusCode = 502; await ctx.Response.WriteAsJsonAsync(new { error = "上游请求失败；请核对连接配置" }); } catch (TaskCanceledException) { ctx.Response.StatusCode = 504; await ctx.Response.WriteAsJsonAsync(new { error = "上游请求超时" }); }
});
app.UseDefaultFiles(); app.UseStaticFiles();
string Space(string space) { Rules.Require(space is "real" or "demo", "无效数据空间"); return space; }
string Id() => Guid.NewGuid().ToString("N");
app.MapGet("/api/health", () => new { status = "ok", boundary = "loopback-single-user", version = "0.1.0" });
app.MapGet("/api/{space}/assets", (string space, Store db) => db.List<Asset>(Space(space), "assets"));
app.MapPut("/api/{space}/assets/{id}", (string space, string id, Asset value, Store db) => { Space(space); Rules.Text(id); Rules.Text(value.Name); Rules.Require(new[] { "physical", "vm", "kubernetes", "application", "middleware", "database" }.Contains(value.Kind), "未知资产类型"); var asset = value with { Id = id, Source = "manual", UpdatedAt = DateTimeOffset.UtcNow }; db.Put(space, "assets", id, asset); return asset; });
app.MapDelete("/api/{space}/assets/{id}", (string space, string id, Store db) => { Space(space); bool deleted = false; db.Atomic(() => { Rules.Require(!db.List<Relation>(space, "relations").Any(r => r.From == id || r.To == id), "请先删除关联关系"); deleted = db.Delete(space, "assets", id); }); return Results.Ok(new { deleted }); });
app.MapGet("/api/{space}/relations", (string space, Store db) => db.List<Relation>(Space(space), "relations"));
app.MapPut("/api/{space}/relations/{id}", (string space, string id, Relation value, Store db) => { Space(space); Rules.Text(id); Rules.Require(value.Kind is "deployed_on" or "belongs_to" or "calls", "无效关系类型"); Relation? result = null; db.Atomic(() => { var ids = db.List<Asset>(space, "assets").Select(x => x.Id).ToHashSet(); Rules.Require(value.From != value.To && ids.Contains(value.From) && ids.Contains(value.To), "关系端点不存在或相同"); Rules.Require(!db.List<Relation>(space, "relations").Any(r => r.Id != id && r.From == value.From && r.To == value.To && r.Kind == value.Kind), "关系已存在"); result = value with { Id = id, Source = "manual", UpdatedAt = DateTimeOffset.UtcNow }; db.Put(space, "relations", id, result); }); return result; });
app.MapDelete("/api/{space}/relations/{id}", (string space, string id, Store db) => Results.Ok(new { deleted = db.Delete(Space(space), "relations", id) }));
// Import an actual Kubernetes List obtained by kubectl get pods -A -o json. No simulated call edges.
app.MapPost("/api/{space}/imports/kubernetes", (string space, JsonElement body, Store db) => { Space(space); Rules.Require(body.TryGetProperty("items", out var items) && items.ValueKind == JsonValueKind.Array && items.GetArrayLength() <= 500, "需要最多500项的 Kubernetes List"); var assets = new List<Asset>(); var relations = new List<Relation>(); foreach (var item in items.EnumerateArray()) { Rules.Require(item.GetProperty("kind").GetString() == "Pod", "仅接受 Pod"); var meta = item.GetProperty("metadata"); var uid = Rules.Text(meta.GetProperty("uid").GetString()); var name = Rules.Text(meta.GetProperty("name").GetString()); var node = Rules.Text(item.GetProperty("spec").GetProperty("nodeName").GetString()); assets.Add(new("pod:" + uid, name, "kubernetes", "kubernetes", false, DateTimeOffset.UtcNow)); assets.Add(new("node:" + node, node, "kubernetes", "kubernetes", false, DateTimeOffset.UtcNow)); relations.Add(new("deploy:" + uid, "pod:" + uid, "node:" + node, "deployed_on", "kubernetes", false, DateTimeOffset.UtcNow)); } int changed = 0; db.Atomic(() => { foreach (var a in assets) { var old = db.List<Asset>(space, "assets").FirstOrDefault(x => x.Id == a.Id); if (old is { Locked: true } || old?.Source == "manual") continue; db.Put(space, "assets", a.Id, a); changed++; } foreach (var r in relations) { var existing = db.List<Relation>(space, "relations"); if (existing.Any(x => (x.Id == r.Id || x.From == r.From && x.Kind == r.Kind) && (x.Locked || x.Source == "manual"))) continue; db.Put(space, "relations", r.Id, r); } }); return new { imported = changed }; });
app.MapGet("/api/{space}/incidents", (string space, Store db) => db.List<Incident>(Space(space), "incidents"));
app.MapPost("/api/{space}/incidents/{id}/diagnose", async (string space, string id, AnalyzeInput input, Store db, IDiagnoser ai) => { Space(space); var incident = db.List<Incident>(space, "incidents").FirstOrDefault(x => x.Id == id); if (incident == null) return Results.NotFound(); var diagnosis = await ai.Analyze(space, incident.Name + " target=" + incident.Target, input.UseModel); db.Atomic(() => { var current = db.List<Incident>(space, "incidents").First(x => x.Id == id); db.Put(space, "incidents", id, current with { Diagnosis = diagnosis }); }); return Results.Ok(diagnosis); });
app.MapPost("/api/webhooks/alertmanager", (HttpContext ctx, JsonElement body, Store db) =>
{
    var key = Environment.GetEnvironmentVariable("AIOPS_WEBHOOK_TOKEN"); if (string.IsNullOrEmpty(key) || !CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(ctx.Request.Headers.Authorization.ToString()), Encoding.UTF8.GetBytes("Bearer " + key))) return Results.Unauthorized();
    Rules.Require(body.TryGetProperty("alerts", out var alerts) && alerts.ValueKind == JsonValueKind.Array && alerts.GetArrayLength() <= 100, "最多100条告警");
    var parsed = new List<(string fp, string name, string severity, string target, string status)>(); foreach (var a in alerts.EnumerateArray()) { var labels = a.GetProperty("labels"); string field(string k, string fallback) => labels.TryGetProperty(k, out var v) ? Rules.Text(v.GetString(), 200) : fallback; var name = field("alertname", "unknown"); var target = field("instance", "unknown"); var status = Rules.Text(a.GetProperty("status").GetString()); Rules.Require(status is "firing" or "resolved", "无效状态"); var canonical = JsonSerializer.Serialize(labels.EnumerateObject().OrderBy(x => x.Name, StringComparer.Ordinal).Select(x => new { x.Name, Value = x.Value.ToString() })); var fp = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))); parsed.Add((fp, Rules.Redact(name), field("severity", "warning"), Rules.Redact(target), status)); }
    db.Atomic(() => { foreach (var a in parsed) { var old = db.List<Incident>("real", "incidents").FirstOrDefault(x => x.Fingerprint == a.fp); var now = DateTimeOffset.UtcNow; var incident = new Incident(old?.Id ?? Id(), a.fp, a.name, a.severity, a.target, a.status, (old?.Count ?? 0) + 1, old?.FirstSeen ?? now, now); db.Put("real", "incidents", incident.Id, incident); } }); return Results.Ok(new { accepted = parsed.Count });
});
app.MapGet("/api/{space}/logs", (string space, string? q, int? hours, int? limit, Store db) => { Space(space); Rules.Require((q?.Length ?? 0) <= 200 && (hours ?? 24) is >= 1 and <= 168 && (limit ?? 100) is >= 1 and <= 200, "查询范围超限"); return db.List<LogEntry>(space, "logs").Where(l => l.UpdatedAt >= DateTimeOffset.UtcNow.AddHours(-(hours ?? 24)) && (q == null || l.Message.Contains(q, StringComparison.OrdinalIgnoreCase))).Take(limit ?? 100); });
app.MapPost("/api/{space}/logs", (string space, LogEntry input, Store db) => { Space(space); Rules.Text(input.System); Rules.Text(input.Message, 10000); Rules.Require(input.Level is "info" or "warning" or "error", "无效日志级别"); var log = input with { Id = Id(), Message = Rules.Redact(input.Message), UpdatedAt = DateTimeOffset.UtcNow }; db.Put(space, "logs", log.Id, log); return log; });
app.MapPost("/api/{space}/analyze", async (string space, AnalyzeInput input, IDiagnoser ai) => { Space(space); Rules.Text(input.Text, 10000); return await ai.Analyze(space, input.Text, input.UseModel); });
app.MapGet("/api/{space}/charts", (string space, Store db) => db.List<Chart>(Space(space), "charts"));
app.MapPost("/api/{space}/charts/interpret", (string space, AnalyzeInput input) => { Space(space); return new { mode = "受控规则解析（未调用模型）", schema = Rules.ChartFromText(input.Text) }; });
app.MapPut("/api/{space}/charts/{id}", (string space, string id, Chart chart, Store db) => { Space(space); Rules.Text(id); Rules.Validate(chart); db.Put(space, "charts", id, chart with { Id = id }); return chart with { Id = id }; });
app.MapDelete("/api/{space}/charts/{id}", (string space, string id, Store db) => Results.Ok(new { deleted = db.Delete(Space(space), "charts", id) }));
app.MapPost("/api/{space}/charts/query", (string space, Chart chart, Store db) => { Space(space); Rules.Validate(chart); var since = DateTimeOffset.UtcNow.AddHours(-chart.Hours); IEnumerable<string> values = chart.Dataset switch { "assets" => db.List<Asset>(space, "assets").Where(x => x.UpdatedAt >= since).Select(x => chart.GroupBy == "kind" ? x.Kind : x.Source), "incidents" => db.List<Incident>(space, "incidents").Where(x => x.UpdatedAt >= since).Select(x => chart.GroupBy == "severity" ? x.Severity : x.Status), _ => db.List<LogEntry>(space, "logs").Where(x => x.UpdatedAt >= since).Select(x => chart.GroupBy == "level" ? x.Level : x.System) }; return values.GroupBy(x => x).Select(g => new { name = g.Key, value = g.Count() }).OrderByDescending(x => x.value).Take(chart.Limit); });
app.MapGet("/api/{space}/settings", (string space, Store db) => db.Config(Space(space)));
app.MapPut("/api/{space}/settings", (string space, Settings config, Store db, Egress egress) => { Space(space); Rules.Require(config.ModelName is not null && config.ModelName.Length <= 100, "模型名超长"); Rules.Require((config.AllowedExternalFields ?? []).All(x => x == "ruleCategory"), "外网仅允许 ruleCategory；禁止原始日志"); if (config.PrometheusUrl != "") egress.Validate(config.PrometheusUrl); if (config.ModelUrl != "") { var u = egress.Validate(config.ModelUrl); var b = IPAddress.Parse(u.Host).GetAddressBytes(); var internalAddress = b[0] == 10 || b[0] == 127 || (b[0] == 172 && b[1] >= 16 && b[1] <= 31) || (b[0] == 192 && b[1] == 168); Rules.Require(internalAddress || config.ExternalModel, "公网模型必须标记为外网模型"); } db.Put(space, "settings", "default", config); return config; });
app.MapGet("/api/{space}/prometheus", async (string space, string? metric, Store db, Egress egress) => { Space(space); Rules.Require(space == "real", "演示空间不访问真实数据源"); Rules.Require(metric is null or "up" or "process_cpu_seconds_total", "仅支持白名单指标"); var url = db.Config(space).PrometheusUrl; if (url == "") return Results.Ok(new { configured = false, message = "Prometheus 未配置" }); var result = await egress.Send(url, "/api/v1/query?query=" + (metric ?? "up") + "&timeout=5s&limit=100"); return Results.Ok(new { configured = true, data = result }); });
app.MapGet("/api/{space}/audit", (string space, Store db) => db.List<Audit>(Space(space), "audit").Take(200));
app.MapPost("/api/demo/seed", (Store db) => { var now = DateTimeOffset.UtcNow; db.Put("demo", "assets", "demo-app", new Asset("demo-app", "演示订单服务", "application", "demo", false, now)); db.Put("demo", "assets", "demo-vm", new Asset("demo-vm", "演示虚拟机", "vm", "demo", false, now)); db.Put("demo", "relations", "demo-rel", new Relation("demo-rel", "demo-app", "demo-vm", "deployed_on", "demo", false, now)); db.Put("demo", "incidents", "demo-alert", new Incident("demo-alert", "demo-fp", "演示 timeout", "warning", "demo-app", "firing", 1, now, now)); db.Put("demo", "logs", "demo-log", new LogEntry("demo-log", "演示订单服务", "error", "DEMO: upstream timeout after 5s", now)); return new { space = "demo", seeded = true }; });
app.Map("/api/{**path}", () => Results.NotFound(new { error = "API 不存在" }));
app.MapFallbackToFile("index.html"); app.Run();
public partial class Program { }
